function solveNQueens(n) {
  const queens = [];                         // queens[r] = the column of the queen in row r
  const result = [];
  const safe = (r, c) => queens.every((qc, qr) => qc !== c && Math.abs(qc - c) !== r - qr);
  const place = (r) => {
    if (r === n) {
      result.push(queens.map((c) => ".".repeat(c) + "Q" + ".".repeat(n - c - 1)));
      return;
    }
    for (let c = 0; c < n; c++) {
      if (!safe(r, c)) continue;             // same column or diagonal as an earlier queen
      queens.push(c);
      place(r + 1);
      queens.pop();
    }
  };
  place(0);
  return result;
}

def solve_n_queens(n):
    queens, result = [], []               # queens[r] = the column of the queen in row r

    def safe(r, c):
        return all(qc != c and abs(qc - c) != r - qr for qr, qc in enumerate(queens))

    def place(r):
        if r == n:
            result.append(["." * c + "Q" + "." * (n - c - 1) for c in queens])
            return
        for c in range(n):
            if not safe(r, c):
                continue                  # same column or diagonal as an earlier queen
            queens.append(c)
            place(r + 1)
            queens.pop()

    place(0)
    return result

