void place(int n, int r, int[] queens, List<List<String>> result) {   // queens[r] = column in row r
    if (r == n) {
        List<String> rows = new ArrayList<>();
        for (int c : queens) rows.add(".".repeat(c) + "Q" + ".".repeat(n - c - 1));
        result.add(rows);
        return;
    }
    for (int c = 0; c < n; c++) {
        boolean safe = true;
        for (int qr = 0; qr < r; qr++) {
            if (queens[qr] == c || Math.abs(queens[qr] - c) == r - qr) { safe = false; break; }
        }
        if (!safe) continue;                     // same column or diagonal as an earlier queen
        queens[r] = c;
        place(n, r + 1, queens, result);
    }
}

