function solveNQueens(n) {
  const cols = new Set(), diag = new Set(), anti = new Set();   // attacked columns and diagonals
  const queens = [];
  const result = [];
  const place = (r) => {
    if (r === n) {                                              // a queen in every row
      result.push(queens.map((c) => ".".repeat(c) + "Q" + ".".repeat(n - c - 1)));
      return;
    }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || diag.has(r - c) || anti.has(r + c)) continue;   // attacked: prune
      cols.add(c); diag.add(r - c); anti.add(r + c);            // place the queen
      queens.push(c);
      place(r + 1);
      queens.pop();                                             // remove it again
      cols.delete(c); diag.delete(r - c); anti.delete(r + c);
    }
  };
  place(0);
  return result;
}

List<List<String>> solveNQueens(int n) {
    List<List<String>> result = new ArrayList<>();
    place(n, 0, new int[n], new boolean[n], new boolean[2 * n], new boolean[2 * n], result);
    return result;
}

void place(int n, int r, int[] queens, boolean[] cols, boolean[] diag, boolean[] anti, List<List<String>> result) {
    if (r == n) {                                // a queen in every row
        List<String> rows = new ArrayList<>();
        for (int c : queens) rows.add(".".repeat(c) + "Q" + ".".repeat(n - c - 1));
        result.add(rows);
        return;
    }
    for (int c = 0; c < n; c++) {
        if (cols[c] || diag[r - c + n] || anti[r + c]) continue;   // attacked: prune
        cols[c] = diag[r - c + n] = anti[r + c] = true;            // place the queen
        queens[r] = c;
        place(n, r + 1, queens, cols, diag, anti, result);
        cols[c] = diag[r - c + n] = anti[r + c] = false;           // remove it again
    }
}

